{
  "audits": [
    {
      "claim_text": "Quillmoor Capital is based in London, UK.",
      "claim_type": "other",
      "verdict": "verified",
      "evidence": "firm_profiles[firm_name=Quillmoor Capital].hq=London, UK"
    },
    {
      "claim_text": "Its cheques range from €500,000 to €3,000,000.",
      "claim_type": "ticket_band",
      "verdict": "verified",
      "evidence": "firm_profiles[firm_name=Quillmoor Capital].cheque_range=EUR 500000-3000000"
    },
    {
      "claim_text": "It's a venture capital firm that invests in fintech, insurtech and regtech companies",
      "claim_type": "other",
      "verdict": "verified",
      "evidence": "firm_profiles[firm_name=Quillmoor Capital].focus_areas=[fintech, insurtech, regtech]"
    },
    {
      "claim_text": "at Seed and Series A",
      "claim_type": "other",
      "verdict": "verified",
      "evidence": "firm_profiles[firm_name=Quillmoor Capital].stages=[Seed, Series A]"
    },
    {
      "claim_text": "The dataset lists 6 companies in its portfolio.",
      "claim_type": "portfolio_company",
      "verdict": "verified",
      "evidence": "firm_profiles[firm_name=Quillmoor Capital].portfolio_count=6"
    }
  ]
}
